// Rust/Tauri implementations of the port interfaces.
//
// Each module here implements the contracts defined in `crate::ports`.
// These are the concrete adapters — when migrating to another platform,
// replace these files with equivalent implementations in the target language.

pub(crate) mod git;
pub(crate) mod handwriting;
pub(crate) mod import;
pub(crate) mod local_sync;
pub(crate) mod notes;
pub(crate) mod platform;
pub(crate) mod profiles;
pub(crate) mod recordings;
pub(crate) mod security;
pub(crate) mod whisper_env;

#[cfg(target_os = "ios")]
pub(crate) mod ios;

// Re-export all adapter symbols so the rest of the crate can use them directly.
pub(crate) use git::*;
pub(crate) use handwriting::*;
pub(crate) use import::*;
pub(crate) use local_sync::*;
pub(crate) use notes::*;
pub(crate) use platform::*;
pub(crate) use profiles::*;
pub(crate) use recordings::*;
pub(crate) use security::*;
pub(crate) use whisper_env::*;

#[cfg(target_os = "ios")]
pub(crate) use ios::*;

use serde::{Deserialize, Serialize};

/// A note's display name and relative path.
#[derive(Serialize)]
pub struct NoteEntry {
    pub name: String,
    pub path: String,
}

/// Metadata returned to the frontend for a single note.
#[derive(Serialize)]
pub struct NoteMeta {
    pub created_ms: Option<i64>,
    pub updated_ms: Option<i64>,
    pub note_type: Option<String>,
    pub archived_ms: Option<i64>,
    pub reviewed_ms: Option<i64>,
    pub recording_audio_path: Option<String>,
    pub handwriting_attachment_path: Option<String>,
    pub transcription_status: Option<String>,
    pub transcription_error: Option<String>,
    pub transcription_updated_ms: Option<i64>,
    pub ocr_status: Option<String>,
    pub ocr_error: Option<String>,
    pub ocr_updated_ms: Option<i64>,
}

/// One note's metadata plus decrypted body, returned in bulk for list previews.
#[derive(Serialize)]
pub struct NotePreviewEntry {
    pub path: String,
    pub content: String,
    pub meta: NoteMeta,
}

/// YAML-ish front-matter fields stored at the top of each markdown note.
#[derive(Default)]
pub struct NoteFrontMatter {
    pub id: Option<String>,
    pub created_ms: Option<i64>,
    pub updated_ms: Option<i64>,
    pub note_type: Option<String>,
    pub archived_ms: Option<i64>,
    pub reviewed_ms: Option<i64>,
    pub recording_audio_path: Option<String>,
    pub handwriting_attachment_path: Option<String>,
    pub transcription_status: Option<String>,
    pub transcription_error: Option<String>,
    pub transcription_updated_ms: Option<i64>,
    pub transcription_id: Option<String>,
    pub ocr_status: Option<String>,
    pub ocr_error: Option<String>,
    pub ocr_updated_ms: Option<i64>,
    pub passthrough_lines: Vec<String>,
}

/// Arguments for setting folder and note ordering within a parent.
#[derive(Deserialize)]
pub struct SetOrderArgs {
    pub parent: String,
    #[serde(rename = "folderOrder")]
    pub folder_order: Vec<String>,
    #[serde(rename = "noteOrder")]
    pub note_order: Vec<String>,
}

/// Arguments for updating a note's created timestamp.
#[derive(Deserialize)]
pub struct SetNoteTimestampArgs {
    pub path: String,
    pub timestamp_ms: i64,
}

/// Arguments for updating feed-related note markers.
#[derive(Deserialize)]
pub struct SetNoteMarkersArgs {
    pub path: String,
    pub archived: Option<bool>,
    pub reviewed: Option<bool>,
}

/// Recursive tree node representing a folder with child folders and notes.
#[derive(Serialize)]
pub struct FolderNode {
    pub name: String,
    pub path: String,
    pub children: Vec<FolderNode>,
    pub notes: Vec<NoteEntry>,
}

/// Persisted sort order for folders and notes within a directory.
#[derive(Default, Deserialize, Serialize)]
pub struct OrderFile {
    #[serde(default)]
    pub folder_order: Vec<String>,
    #[serde(default)]
    pub note_order: Vec<String>,
}

/// Filename format strategy for new notes.
#[derive(Clone, Copy, Debug, Default, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum NoteFileNameFormat {
    #[default]
    UtcTimestampSlug,
    UuidV7,
    UuidV7PrefixSlug,
}

/// Arguments for creating a new note.
#[derive(Deserialize)]
pub struct CreateNoteArgs {
    pub folder_path: Option<String>,
    pub content: Option<String>,
    pub timestamp_ms: Option<i64>,
    #[serde(default)]
    pub file_name_format: NoteFileNameFormat,
}

/// Result returned after creating a note, containing its relative path.
#[derive(Serialize)]
pub struct CreateNoteResult {
    pub path: String,
}

