1	use std::{collections::HashMap, path::PathBuf};
2	
3	use crate::{
4	    ports::notes::{
5	        NoteBodyCrypto, NoteClock, NoteDocumentCodec, NoteIdGenerator, NoteStorageEntryKind,
6	        NotesRepository,
7	    },
8	    CreateNoteArgs, CreateNoteResult, FolderNode, NoteFrontMatter, NoteMeta, NotePreviewEntry,
9	    OrderFile, SetNoteTimestampArgs, SetOrderArgs, FEED_FOLDER,
10	};
11	
12	/// Note use cases. This layer owns workflow and policy while persistence,
13	/// document parsing, encryption, IDs, and time are supplied as ports.
14	pub(crate) struct NotesService<R, D, C, I, T> {
15	    repository: R,
16	    documents: D,
17	    crypto: C,
18	    ids: I,
19	    clock: T,
20	}
21	
22	impl<R, D, C, I, T> NotesService<R, D, C, I, T>
23	where
24	    R: NotesRepository,
25	    D: NoteDocumentCodec,
26	    C: NoteBodyCrypto,
27	    I: NoteIdGenerator,
28	    T: NoteClock,
29	{
30	    pub(crate) fn new(repository: R, documents: D, crypto: C, ids: I, clock: T) -> Self {
31	        Self {
32	            repository,
33	            documents,
34	            crypto,
35	            ids,
36	            clock,
37	        }
38	    }
39	
40	    pub(crate) fn get_tree(&self) -> Result<FolderNode, String> {
41	        self.repository.ensured_root()?;
42	        self.repository.build_tree()
43	    }
44	
45	    pub(crate) fn read_note(&self, path: &str) -> Result<String, String> {
46	        let full_path = self.repository.resolve_path(path)?;
47	        if self.repository.entry_kind(&full_path)? != Some(NoteStorageEntryKind::File) {
48	            return Err("Note file does not exist.".to_string());
49	        }
50	        let raw = self.repository.read_to_string(&full_path)?;
51	        let (_, body) = self.documents.parse(&raw);
52	        self.crypto.decrypt_note_body(&body)
53	    }
54	
55	    pub(crate) fn create_note(&self, args: CreateNoteArgs) -> Result<CreateNoteResult, String> {
56	        self.repository.ensured_root()?;
57	        let folder_rel = args
58	            .folder_path
59	            .as_deref()
60	            .map(str::trim)
61	            .filter(|value| !value.is_empty())
62	            .unwrap_or(FEED_FOLDER);
63	        let folder_full = self.repository.resolve_path(folder_rel)?;
64	        if self.repository.is_storage_folder_path(&folder_full) {
65	            return Err(
66	                "Notes cannot be created inside recordings or attachments storage.".to_string(),
67	            );
68	        }
69	        self.repository.create_dir_all(&folder_full)?;
70	
71	        let timestamp = args
72	            .timestamp_ms
73	            .or_else(|| self.clock.now_ms())
74	            .unwrap_or(0);
75	        let content = args.content.unwrap_or_default();
76	        let note_id = self.ids.generate_note_id();
77	        let fallback = format!(
78	            "note-{}",
79	            self.ids.uuid_tail_without_timestamp_prefix(&note_id)
80	        );
81	        let file_name = self.repository.allocate_note_file_name(
82	            &folder_full,
83	            timestamp,
84	            &note_id,
85	            &content,
86	            &fallback,
87	            args.file_name_format,
88	        )?;
89	        let path = folder_full.join(&file_name);
90	        let mut meta = NoteFrontMatter::default();
91	        meta.id = Some(note_id);
92	        meta.created_ms = Some(timestamp);
93	        meta.updated_ms = Some(timestamp);
94	        self.repository.write_note(&path, &meta, &content)?;
95	        if !self.repository.is_feed_folder_path(&folder_full) {
96	            self.repository
97	                .update_order_append(&folder_full, &[file_name], false)?;
98	        }
99	
100	        Ok(CreateNoteResult {
101	            path: self.repository.strip_root(&path),
102	        })
103	    }
104	
105	    pub(crate) fn write_note(&self, path: &str, content: &str) -> Result<(), String> {
106	        let full_path = self.repository.resolve_path(path)?;
107	        if let Some(parent) = full_path.parent() {
