265	    pub(crate) fn move_items(&self, items: Vec<String>, destination: String) -> Result<(), String> {
266	        self.repository.ensured_root()?;
267	        let destination_path = self.repository.resolve_path(&destination)?;
268	        if self.repository.entry_kind(&destination_path)? != Some(NoteStorageEntryKind::Directory) {
269	            self.repository.create_dir_all(&destination_path)?;
270	        }
271	
272	        let mut source_groups_folders: HashMap<PathBuf, Vec<String>> = HashMap::new();
273	        let mut source_groups_notes: HashMap<PathBuf, Vec<String>> = HashMap::new();
274	        let mut moved_folder_names = Vec::new();
275	        let mut moved_note_names = Vec::new();
276	
277	        for item in items {
278	            let source = self.repository.resolve_path(&item)?;
279	            if self.repository.is_system_folder_path(&source) {
280	                return Err(format!(
281	                    "Cannot move system folder: {}",
