288	                    "Source does not exist: {}",
289	                    source.to_string_lossy()
290	                ));
291	            }
292	            let name = source
293	                .file_name()
294	                .and_then(|n| n.to_str())
295	                .ok_or_else(|| "Invalid item name.".to_string())?
296	                .to_string();
297	            let parent = source
298	                .parent()
299	                .ok_or_else(|| "Missing parent folder.".to_string())?
300	                .to_path_buf();
301	
302	            let target = destination_path.join(&name);
303	            self.repository.rename(&source, &target).map_err(|err| {
304	                format!(
305	                    "Move failed {} -> {}: {}",
306	                    source.to_string_lossy(),
307	                    target.to_string_lossy(),
308	                    err
309	                )
310	            })?;
311	            if source_kind == Some(NoteStorageEntryKind::Directory) {
312	                source_groups_folders
313	                    .entry(parent)
314	                    .or_default()
315	                    .push(name.clone());
316	                moved_folder_names.push(name);
317	            } else {
318	                source_groups_notes
319	                    .entry(parent)
320	                    .or_default()
321	                    .push(name.clone());
322	                moved_note_names.push(name);
323	            }
324	        }
325	
326	        for (parent, names) in source_groups_folders {
327	            self.repository.update_order_remove(&parent, &names, true)?;
328	        }
329	
330	        for (parent, names) in source_groups_notes {
331	            self.repository
332	                .update_order_remove(&parent, &names, false)?;
333	        }
334	
335	        if !moved_folder_names.is_empty() {
336	            self.repository
337	                .update_order_append(&destination_path, &moved_folder_names, true)?;
338	        }
339	        if !moved_note_names.is_empty() {
340	            self.repository
341	                .update_order_append(&destination_path, &moved_note_names, false)?;
342	        }
343	
344	        Ok(())
345	    }
