347	    pub(crate) fn delete_items(&self, items: Vec<String>) -> Result<(), String> {
348	        self.repository.ensured_root()?;
349	        let mut parent_folder_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
350	        let mut parent_note_groups: HashMap<PathBuf, Vec<String>> = HashMap::new();
351	
352	        for item in items {
353	            let full_path = self.repository.resolve_path(&item)?;
354	            if self.repository.is_system_folder_path(&full_path) {
355	                return Err(format!(
356	                    "Cannot delete system folder: {}",
