362	                .and_then(|n| n.to_str())
363	                .ok_or_else(|| "Invalid item name.".to_string())?
364	                .to_string();
365	            let parent = full_path
366	                .parent()
367	                .ok_or_else(|| "Missing parent folder.".to_string())?
368	                .to_path_buf();
369	            let kind = self
370	                .repository
371	                .entry_kind(&full_path)?
372	                .ok_or_else(|| "Item does not exist.".to_string())?;
373	            if kind == NoteStorageEntryKind::Directory {
374	                self.repository.remove_dir_all(&full_path)?;
375	                parent_folder_groups.entry(parent).or_default().push(name);
376	            } else {
377	                self.repository.remove_file(&full_path)?;
378	                parent_note_groups.entry(parent).or_default().push(name);
379	            }
380	        }
381	
382	        for (parent, names) in parent_folder_groups {
383	            self.repository.update_order_remove(&parent, &names, true)?;
384	        }
385	
386	        for (parent, names) in parent_note_groups {
387	            self.repository
388	                .update_order_remove(&parent, &names, false)?;
389	        }
390	
391	        Ok(())
392	    }
393	
394	    pub(crate) fn rename_item(&self, path: &str, new_name: &str) -> Result<String, String> {
395	        self.repository.ensured_root()?;
396	        let full_path = self.repository.resolve_path(path)?;
397	        if self.repository.is_system_folder_path(&full_path) {
398	            return Err(format!(
399	                "Cannot rename system folder: {}",
400	                full_path.to_string_lossy()
401	            ));
402	        }
403	        let parent = full_path
404	            .parent()
405	            .ok_or_else(|| "Missing parent folder.".to_string())?;
406	        let old_name = full_path
407	            .file_name()
408	            .and_then(|name| name.to_str())
409	            .ok_or_else(|| "Invalid item name.".to_string())?
410	            .to_string();
411	        let is_folder =
412	            self.repository.entry_kind(&full_path)? == Some(NoteStorageEntryKind::Directory);
413	        let new_path = parent.join(new_name);
414	        self.repository.rename(&full_path, &new_path)?;
415	        self.repository
416	            .update_order_rename(parent, &old_name, new_name, is_folder)?;
