664	fn process_transcription_job(job: QueuedTranscriptionJob) {
665	    if let Err(error) = update_recording_note_status(
666	        &job.note_path,
667	        RECORDING_STATUS_PROCESSING,
668	        None,
669	        None,
670	        None,
671	    ) {
672	        eprintln!(
673	            "[recordings] failed to mark processing for {}: {}",
674	            job.note_rel, error
675	        );
676	    }
677	
678	    let result = match &job.method {
679	        TranscriptionMethod::LocalWhisper { model, app } => {
680	            // Provision the managed Python env on first use; subsequent jobs are
681	            // instant. Any setup failure surfaces as the note's transcription error.
682	            match crate::ensure_whisper_env(app) {
683	                Ok(python) => transcribe_audio_local_whisper(&job.audio_path, model, &python),
684	                Err(error) => Err(format!("Failed to set up local transcription: {error}")),
685	            }
686	        }
687	        TranscriptionMethod::AssemblyAi { api_key } => {
688	            let audio_bytes = match fs::read(&job.audio_path) {
689	                Ok(bytes) => bytes,
690	                Err(e) => {
691	                    let _ = update_recording_note_status(
692	                        &job.note_path,
