695	                        None,
696	                        None,
697	                    );
698	                    eprintln!(
699	                        "[recordings] failed to read audio for {}: {}",
700	                        job.note_rel, e
701	                    );
702	                    return;
703	                }
704	            };
705	            transcribe_audio_bytes_with_assembly(audio_bytes, api_key)
706	        }
707	    };
708	
709	    match result {
710	        Ok((transcript, id_or_json)) => {
711	            // For local whisper, id_or_json is the full JSON with word timestamps.
712	            // Save word-level JSON alongside the audio file.
713	            if matches!(job.method, TranscriptionMethod::LocalWhisper { .. }) {
714	                if let Err(e) = save_word_level_json(&job.audio_path, &id_or_json) {
715	                    eprintln!(
