756	/// Start a background worker thread if jobs are queued and none is running.
757	pub fn spawn_transcription_worker_if_needed() {
758	    let should_spawn = {
759	        let queue = transcription_queue_state();
760	        let mut state = queue.lock().expect("transcription queue poisoned");
761	        if state.running || state.pending.is_empty() {
762	            false
763	        } else {
764	            state.running = true;
765	            true
766	        }
767	    };
768	    if !should_spawn {
769	        return;
770	    }
771	    thread::spawn(move || loop {
772	        let maybe_job = {
773	            let queue = transcription_queue_state();
774	            let mut state = queue.lock().expect("transcription queue poisoned");
775	            match state.pending.pop_front() {
776	                Some(job) => {
777	                    state.current_recording = Some(job.note_rel.clone());
778	                    Some(job)
779	                }
780	                None => {
781	                    state.running = false;
782	                    state.current_recording = None;
783	                    None
784	                }
785	            }
786	        };
787	        let Some(job) = maybe_job else {
788	            break;
789	        };
790	        process_transcription_job(job.clone());
791	        let queue = transcription_queue_state();
792	        let mut state = queue.lock().expect("transcription queue poisoned");
793	        state.known_recordings.remove(&job.note_rel);
794	        if state.current_recording.as_deref() == Some(job.note_rel.as_str()) {
795	            state.current_recording = None;
796	        }
797	    });
798	}
