1	//! UniFFI bindings over [`type_core`] for non-Tauri shells — React Native via
2	//! uniffi-bindgen-react-native, or any UniFFI-supported host (Swift/Kotlin).
3	//!
4	//! Design:
5	//! - The Tauri shell speaks JSON over IPC, and this crate mirrors that
6	//!   contract: structured inputs arrive as JSON strings deserialized into the
7	//!   same serde arg structs the desktop commands use, and structured outputs
8	//!   are returned as JSON strings. One set of TypeScript types therefore fits
9	//!   both shells.
10	//! - Every exported function is async: core work runs on the Tokio blocking
11	//!   pool so long git/transcription calls never block the host's JS thread.
12	//! - [`init_core`] must be called with the app's data directory before any
13	//!   other function.
14	//! - Transcription is pluggable: hosts implement [`TranscriptionProvider`]
15	//!   (a foreign trait) and pass it to `queue_provider_transcriptions` to run
16	//!   e.g. native on-device speech recognition against pending recordings.
17	
18	uniffi::setup_scaffolding!();
19	
20	mod git_sync;
21	mod notes;
22	mod profiles;
23	mod recordings;
24	mod security;
25	
26	pub use git_sync::*;
27	pub use notes::*;
28	pub use profiles::*;
29	pub use recordings::*;
30	pub use security::*;
31	
32	#[cfg(test)]
33	mod tests;
34	
35	use std::sync::RwLock;
36	use type_core::AppEnv;
37	
38	// ── Errors ─────────────────────────────────────────────────────────────────────
39	
40	/// Error surfaced across the FFI boundary. Core reports errors as strings;
41	/// this wraps them so bindings raise a typed exception with the message.
42	#[derive(Debug, uniffi::Error)]
43	#[uniffi(flat_error)]
44	pub enum CoreError {
45	    Failure(String),
46	}
47	
48	impl std::fmt::Display for CoreError {
49	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
50	        match self {
51	            CoreError::Failure(message) => write!(f, "{message}"),
52	        }
53	    }
54	}
55	
56	impl std::error::Error for CoreError {}
57	
58	impl From<String> for CoreError {
59	    fn from(message: String) -> Self {
60	        CoreError::Failure(message)
61	    }
62	}
63	
64	// ── App environment ────────────────────────────────────────────────────────────
65	
66	static APP_ENV: RwLock<Option<AppEnv>> = RwLock::new(None);
67	
68	/// Initialize the core with the host app's directories. Must be called before
69	/// any other function. Idempotent — calling it again (e.g. after a React
70	/// Native reload) replaces the environment.
71	#[uniffi::export]
72	pub fn init_core(app_data_dir: String, documents_dir: Option<String>) -> Result<(), CoreError> {
73	    let mut env = AppEnv::new(app_data_dir);
74	    if let Some(dir) = documents_dir {
75	        env = env.with_documents_dir(dir);
76	    }
77	    // Mirrors the Tauri shell's setup hook: load persisted security config so
78	    // the locked/unlocked gate is correct before the first command runs.
79	    type_core::ensure_security_runtime_initialized_for_setup(&env)?;
80	    *APP_ENV.write().expect("app env lock poisoned") = Some(env);
81	    Ok(())
82	}
83	
84	/// The environment registered by [`init_core`].
85	pub(crate) fn current_env() -> Result<AppEnv, String> {
86	    APP_ENV
87	        .read()
88	        .expect("app env lock poisoned")
89	        .clone()
90	        .ok_or_else(|| "Core is not initialized — call init_core first.".to_string())
91	}
92	
93	/// [`current_env`] plus the same lock gate the desktop commands apply: fails
94	/// while encrypted mode is locked so note bodies are never served locked.
95	pub(crate) fn unlocked_env() -> Result<AppEnv, String> {
96	    let env = current_env()?;
97	    type_core::ensure_security_unlocked_for_app(&env)?;
98	    Ok(env)
99	}
100	
101	// ── Shared helpers ─────────────────────────────────────────────────────────────
102	
103	/// Run a blocking core workflow on the Tokio blocking pool.
104	pub(crate) async fn run_blocking<T, F>(task: F) -> Result<T, CoreError>
105	where
106	    T: Send + 'static,
107	    F: FnOnce() -> Result<T, String> + Send + 'static,
108	{
109	    tokio::task::spawn_blocking(task)
110	        .await
111	        .map_err(|error| CoreError::Failure(format!("Background task failed: {error}")))?
112	        .map_err(CoreError::from)
113	}
114	
115	pub(crate) fn to_json<T: serde::Serialize>(value: &T) -> Result<String, String> {
116	    serde_json::to_string(value).map_err(|error| format!("Failed to serialize response: {error}"))
117	}
118	
119	pub(crate) fn from_json<T: serde::de::DeserializeOwned>(json: &str) -> Result<T, String> {
120	    serde_json::from_str(json).map_err(|error| format!("Invalid arguments: {error}"))
121	}
