1	import type {
2	  HandwritingOcrListItem,
3	  NoteMeta,
4	  RecordingListItem,
5	} from "../types";
6	import { stripFrontmatter } from "./frontmatter";
7	import { stripInlineAnnotationMetadata } from "./annotation-metadata";
8	
9	const RECORDING_NOTE_TYPE = "audio_recording";
10	const HANDWRITING_NOTE_TYPE = "handwriting_attachment";
11	
12	const stripMarkdownLine = (line: string) =>
13	  line
14	    .replace(/\\+_/g, "_")
15	    .replace(/NV_EMPTY_LINE_TOKEN_[A-Za-z0-9]+/gi, " ")
16	    .replace(/NV[\s_]+EMPTY[\s_]+LINE[\s_]+TOKEN(?:[\s_]+[A-Za-z0-9]+)?/gi, " ")
17	    .replace(/^#{1,6}\s+/, "")
18	    .replace(/^[>\-+*]\s+/, "")
19	    .replace(/!\[([^\]]*)\]\([^)]+\)/g, "$1")
20	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
21	    .replace(/[*_~`]/g, "")
22	    .replace(/\s+/g, " ")
23	    .trim();
24	
25	const isRecordingNoiseLine = (line: string) =>
26	  /^recording$/i.test(line) ||
27	  /^transcript$/i.test(line) ||
28	  /^<!--\s*recording-transcript:(start|end)\s*-->$/i.test(line) ||
29	  /^\(transcription(?:\s+\w+)*\.\)$/i.test(line) ||
30	  /^error:\s*/i.test(line);
31	
32	export const isRecordingNoteType = (
33	  noteType: string | null | undefined,
34	  recordingAudioPath: string | null | undefined
35	) =>
36	  noteType === RECORDING_NOTE_TYPE || Boolean(recordingAudioPath && recordingAudioPath.trim());
37	
38	export const isHandwritingNoteType = (
39	  noteType: string | null | undefined,
40	  handwritingAttachmentPath: string | null | undefined
41	) =>
42	  noteType === HANDWRITING_NOTE_TYPE ||
43	  Boolean(handwritingAttachmentPath && handwritingAttachmentPath.trim());
44	
45	export const isRecordingTranscriptionCompleted = (
46	  status: string | null | undefined
47	) => (status || "").trim().toLowerCase() === "completed";
48	
49	export const isHandwritingOcrCompleted = (status: string | null | undefined) =>
50	  (status || "").trim().toLowerCase() === "completed";
51	
52	export const sanitizeRecordingEditorContent = (
53	  content: string,
54	  transcriptionStatus: string | null | undefined
55	) => {
56	  if (isRecordingTranscriptionCompleted(transcriptionStatus)) {
57	    return content;
58	  }
59	  const filteredLines = content
60	    .split(/\r?\n/)
61	    .filter((line) => !isRecordingNoiseLine(stripMarkdownLine(line)));
62	  return filteredLines.join("\n").replace(/\n{3,}/g, "\n\n");
63	};
64	
65	export const formatRecordingStatusLabel = (status: string | null | undefined) => {
66	  const normalized = (status || "").trim().toLowerCase();
67	  if (!normalized) {
68	    return "Unknown";
69	  }
70	  if (normalized === "pending") {
71	    return "Pending";
72	  }
73	  if (normalized === "queued") {
74	    return "Queued";
75	  }
76	  if (normalized === "processing") {
77	    return "Processing";
78	  }
79	  if (normalized === "completed") {
80	    return "Completed";
81	  }
82	  if (normalized === "failed") {
83	    return "Failed";
84	  }
85	  return normalized[0].toUpperCase() + normalized.slice(1);
86	};
87	
88	export type NotePreview = {
89	  title: string;
90	  dateLabel: string;
91	  secondLine: string;
92	  createdMs: number | null;
93	  updatedMs: number | null;
94	  archivedMs: number | null;
95	  reviewedMs: number | null;
96	  isArchived: boolean;
97	  isReviewed: boolean;
98	  isRecording: boolean;
99	  isHandwriting: boolean;
100	  recordingAudioPath: string | null;
101	  handwritingAttachmentPath: string | null;
102	  transcriptionStatus: string | null;
103	  ocrStatus: string | null;
104	};
105	
106	export const formatNoteDateLabel = (timestamp: number | null) => {
107	  if (!timestamp) {
108	    return "";
109	  }
110	  const value = new Date(timestamp);
111	  const now = new Date();
112	  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
113	  const itemStart = new Date(
114	    value.getFullYear(),
115	    value.getMonth(),
116	    value.getDate()
117	  );
118	  const diffDays = Math.floor(
119	    (todayStart.getTime() - itemStart.getTime()) / 86_400_000
120	  );
121	  if (diffDays <= 0) {
122	    return value.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
123	  }
124	  if (diffDays === 1) {
125	    return "yesterday";
126	  }
127	  if (diffDays < 7) {
128	    return value.toLocaleDateString([], { weekday: "long" }).toLowerCase();
129	  }
130	  if (value.getFullYear() === now.getFullYear()) {
131	    return value.toLocaleDateString([], {
132	      day: "numeric",
133	      month: "short",
134	    });
135	  }
136	  return value.toLocaleDateString([], {
137	    day: "2-digit",
138	    month: "2-digit",
139	    year: "numeric",
140	  });
141	};
142	
143	export const parseNotePreview = (
144	  content: string,
145	  updatedMs: number | null,
146	  noteMeta?: Pick<
147	    NoteMeta,
148	    | "created_ms"
149	    | "note_type"
150	    | "archived_ms"
151	    | "reviewed_ms"
152	    | "recording_audio_path"
153	    | "handwriting_attachment_path"
154	    | "transcription_status"
155	    | "ocr_status"
156	  >
157	): NotePreview => {
158	  const isRecording = isRecordingNoteType(
159	    noteMeta?.note_type,
160	    noteMeta?.recording_audio_path
161	  );
162	  const isHandwriting = isHandwritingNoteType(
163	    noteMeta?.note_type,
164	    noteMeta?.handwriting_attachment_path
165	  );
166	  const transcriptionStatus = noteMeta?.transcription_status || null;
167	  const ocrStatus = noteMeta?.ocr_status || null;
168	  const isTranscribed = isRecordingTranscriptionCompleted(transcriptionStatus);
169	  const isOcrComplete = isHandwritingOcrCompleted(ocrStatus);
170	  const contentWithoutFrontmatter = stripInlineAnnotationMetadata(
171	    stripFrontmatter(content)
172	  );
173	  const createdMs = noteMeta?.created_ms ?? null;
174	  const archivedMs = noteMeta?.archived_ms ?? null;
175	  const reviewedMs = noteMeta?.reviewed_ms ?? null;
176	
177	  const previewLines: string[] = [];
178	  const sourceContent =
179	    isRecording && !isTranscribed
180	      ? sanitizeRecordingEditorContent(contentWithoutFrontmatter, transcriptionStatus)
181	      : contentWithoutFrontmatter;
182	  for (const rawLine of sourceContent.split(/\r?\n/)) {
183	    const line = stripMarkdownLine(rawLine);
184	    if (!line || isRecordingNoiseLine(line)) {
185	      continue;
186	    }
187	    previewLines.push(line);
188	    if (previewLines.length >= 2) {
189	      break;
190	    }
191	  }
192	
193	  const useVoiceRecordingPlaceholder =
194	    isRecording && !isTranscribed && previewLines.length === 0;
195	  const useHandwritingPlaceholder =
196	    isHandwriting && !isOcrComplete && previewLines.length === 0;
197	  const title =
198	    useVoiceRecordingPlaceholder
199	      ? "Voice recording"
200	      : useHandwritingPlaceholder
201	        ? "Handwriting note"
202	        : previewLines[0] || "";
203	  const secondLine = useVoiceRecordingPlaceholder ? "" : previewLines[1] || "";
204	  return {
205	    title,
206	    dateLabel: formatNoteDateLabel(updatedMs),
207	    secondLine,
208	    createdMs,
209	    updatedMs,
210	    archivedMs,
211	    reviewedMs,
212	    isArchived: Boolean(archivedMs),
213	    isReviewed: Boolean(reviewedMs),
214	    isRecording,
215	    isHandwriting,
216	    recordingAudioPath: noteMeta?.recording_audio_path || null,
217	    handwritingAttachmentPath: noteMeta?.handwriting_attachment_path || null,
218	    transcriptionStatus,
219	    ocrStatus,
220	  };
221	};
222	
223	export const getNextNoteFileName = (existingNames: string[]) => {
224	  const used = new Set(existingNames.map((name) => name.toLowerCase()));
225	  let index = 1;
226	  while (true) {
227	    const candidate = index === 1 ? "New note.md" : `New note ${index}.md`;
228	    if (!used.has(candidate.toLowerCase())) {
229	      return candidate;
230	    }
231	    index += 1;
232	  }
233	};
234	
235	export const formatRecordingStatus = (item: RecordingListItem) => {
236	  if (item.is_processing) {
237	    return "processing";
238	  }
239	  if (item.is_queued) {
240	    return "queued";
241	  }
242	  return item.status;
243	};
244	
245	export const formatHandwritingStatus = (item: HandwritingOcrListItem) => {
246	  if (item.is_processing) {
247	    return "processing";
248	  }
249	  if (item.is_queued) {
250	    return "queued";
251	  }
252	  return item.status;
253	};
254	
255	export const formatUpdatedAt = (updatedMs: number | null) => {
256	  if (!updatedMs) {
257	    return "never";
258	  }
259	  const date = new Date(updatedMs);
260	  if (Number.isNaN(date.getTime())) {
261	    return "never";
262	  }
263	  return date.toLocaleString();
264	};
265	
266	export const formatHistoryTime = (value: string) => {
267	  const parsed = new Date(value);
268	  if (Number.isNaN(parsed.getTime())) {
269	    return value;
270	  }
271	  return parsed.toLocaleString();
272	};
273	
274	export const formatGitCommitTime = (value: number | null) => {
275	  if (!value) {
276	    return "Unknown time";
277	  }
278	  const parsed = new Date(value);
279	  if (Number.isNaN(parsed.getTime())) {
280	    return "Unknown time";
281	  }
282	  return parsed.toLocaleString();
