1	import { useRef, type ReactNode } from "react";
2	import { useShallow } from "zustand/react/shallow";
3	
4	import { AppearanceProvider } from "@/app/state/appearance-store";
5	import { SelectionProvider, useSelection } from "@/app/state/selection-store";
6	import { EditorProvider, useEditor } from "@/features/notes/editor/hooks/editor-context";
7	import { HandwritingProvider } from "@/features/handwriting/hooks/handwriting-context";
8	import { NotesTreeProvider, useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
9	import { ProfilesProvider } from "@/features/profiles/hooks/profiles-context";
10	import { RecordingsProvider } from "@/features/recording/hooks/recordings-context";
11	import { SecurityProvider } from "@/features/security/hooks/security-context";
12	import { GitSyncProvider } from "@/features/sync/hooks/git-sync-context";
13	import { useLayoutMode } from "@/mobile/use-layout-mode";
14	import { useBackgroundSave } from "./lifecycle/use-background-save";
15	import { AppReadinessGate, AppSecurityGate } from "./readiness";
16	
17	function FlushSaveBridge({
18	  flushSaveRef,
19	}: {
20	  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
21	}) {
22	  const { flushSave } = useEditor();
23	  flushSaveRef.current = flushSave;
24	  return null;
25	}
26	
27	function AppLifecycle() {
28	  const { flushSave } = useEditor();
29	  useBackgroundSave(flushSave);
30	  return null;
31	}
32	
33	function CaptureFeatureProviders({ children }: { children: ReactNode }) {
34	  const notesTree = useNotesTree();
35	  const selection = useSelection(
36	    useShallow((state) => ({
37	      activeFolder: state.activeFolder,
38	      setSelectedFolders: state.setSelectedFolders,
39	      setLastSelectedFolder: state.setLastSelectedFolder,
40	      setActiveFolder: state.setActiveFolder,
41	      setSelectedNotes: state.setSelectedNotes,
42	      setLastSelectedNote: state.setLastSelectedNote,
43	      setActiveNote: state.setActiveNote,
44	    }))
45	  );
46	  const editor = useEditor();
47	  const layoutMode = useLayoutMode();
48	
49	  const handleCapturedNoteComplete = async (result: {
50	    folder_path: string;
51	    note_path: string;
52	  }) => {
53	    await notesTree.refreshTree();
54	    selection.setSelectedFolders(new Set([result.folder_path]));
55	    selection.setLastSelectedFolder(result.folder_path);
56	    selection.setActiveFolder(result.folder_path);
57	    selection.setSelectedNotes(new Set([result.note_path]));
58	    selection.setLastSelectedNote(result.note_path);
59	    selection.setActiveNote(result.note_path);
60	    editor.clearDraft();
61	  };
62	
63	  return (
64	    <RecordingsProvider
65	      activeFolder={selection.activeFolder}
66	      layoutMode={layoutMode}
67	      onRecordingComplete={handleCapturedNoteComplete}
68	    >
69	      <HandwritingProvider
70	        activeFolder={selection.activeFolder}
71	        layoutMode={layoutMode}
72	        onHandwritingComplete={handleCapturedNoteComplete}
73	      >
74	        {children}
75	      </HandwritingProvider>
76	    </RecordingsProvider>
77	  );
78	}
79	
80	function UnlockedAppProviders({
81	  children,
82	  flushSaveRef,
83	}: {
84	  children: ReactNode;
85	  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
86	}) {
87	  return (
88	    <ProfilesProvider flushSaveRef={flushSaveRef}>
89	      <GitSyncProvider>
90	        <SelectionProvider>
91	          <EditorProvider>
92	            <NotesTreeProvider>
93	              <FlushSaveBridge flushSaveRef={flushSaveRef} />
94	              <AppLifecycle />
95	              <AppReadinessGate>
96	                <CaptureFeatureProviders>{children}</CaptureFeatureProviders>
97	              </AppReadinessGate>
98	            </NotesTreeProvider>
99	          </EditorProvider>
100	        </SelectionProvider>
101	      </GitSyncProvider>
102	    </ProfilesProvider>
103	  );
104	}
105	
106	export function AppProviders({ children }: { children: ReactNode }) {
107	  const flushSaveRef = useRef<(() => Promise<void>) | null>(null);
108	
109	  return (
110	    <AppearanceProvider>
111	      <SecurityProvider>
112	        <AppSecurityGate>
113	          <UnlockedAppProviders flushSaveRef={flushSaveRef}>
114	            {children}
115	          </UnlockedAppProviders>
116	        </AppSecurityGate>
