pub(super) fn read_recording_audio(
    app: tauri::AppHandle,
    args: ReadRecordingAudioArgs,
) -> Result<RecordingAudioPayload, String> {
    ensure_security_unlocked_for_app(&crate::app_env(&app)?)?;
    recordings_use_cases(app)?.read_audio(args)
}
