import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useState,
  type ReactNode,
} from "react";
import * as api from "../api/recordings-api";
import type { RecordingListItem, RecordingQueueSnapshot } from "@typenotes/shared/types";
import { FEED_FOLDER_PATH } from "@typenotes/shared/constants";
import { toBase64, fromBase64 } from "@/shared/lib/notes";
import { useAudioRecorder } from "./use-audio-recorder";
import { useProfiles } from "@/features/profiles/hooks/profiles-context";
import { useAutoQueueLoop } from "@/features/processing/hooks/use-auto-queue-loop";
import { useProcessingQueue } from "@/features/processing/hooks/use-processing-queue";
import { jobListSignature } from "@typenotes/shared/jobs";
import { getErrorMessage } from "@typenotes/shared/errors";

type RecordingsContextValue = {
  recordingSupported: boolean;
  isRecordingAudio: boolean;
  isRecordingFinalizing: boolean;
  recorderError: string | null;
  recordingElapsedLabel: string | null;
  recordingStatusMessage: string | null;
  transcriptionQueueBusy: boolean;
  recordingsQueue: RecordingQueueSnapshot | null;
  recordingsList: RecordingListItem[];
  recordingsBusy: boolean;
  recordingsError: string | null;
  activeAudioPath: string | null;
  activeAudioSrc: string | null;
  startRecording: (preferredFolderPath?: string | null) => void;
  stopRecording: () => void;
  refreshRecordings: () => Promise<void>;
  playRecording: (audioPath: string) => Promise<void>;
  queueRecordingTranscriptions: (trigger?: "manual" | "auto") => Promise<void>;
  retriggerTranscription: (notePath: string) => Promise<void>;
};

const RecordingsContext = createContext<RecordingsContextValue | null>(null);

export function RecordingsProvider({
  children,
  activeFolder,
  onRecordingComplete,
}: {
  children: ReactNode;
  activeFolder: string;
  onRecordingComplete: (result: {
    folder_path: string;
    note_path: string;
    audio_path: string;
  }) => Promise<void>;
}) {
  const { syncSettings } = useProfiles();
  const [recordingStatusMessage, setRecordingStatusMessage] = useState<string | null>(null);
  const [transcriptionQueueBusy, setTranscriptionQueueBusy] = useState(false);
  const [activeAudioPath, setActiveAudioPath] = useState<string | null>(null);
  const [activeAudioSrc, setActiveAudioSrc] = useState<string | null>(null);

  const transcriptionQueueBusyRef = useRef(false);
  const recordingTargetFolderRef = useRef<string>(FEED_FOLDER_PATH);
  const activeAudioObjectUrlRef = useRef<string | null>(null);

  const cleanupMissingActiveAudio = useCallback(
    (snapshot: { items: RecordingListItem[] }) => {
      if (!activeAudioPath) {
        return;
      }
      const stillExists = snapshot.items.some(
        (item) => item.audio_path === activeAudioPath
      );
      if (stillExists) {
        return;
      }
      if (activeAudioObjectUrlRef.current) {
        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
        activeAudioObjectUrlRef.current = null;
      }
      setActiveAudioPath(null);
      setActiveAudioSrc(null);
    },
    [activeAudioPath]
  );

  const loadRecordingsSnapshot = useCallback(async () => {
    const snapshot = await api.listRecordings();
    return {
      queue: snapshot.queue,
      items: snapshot.recordings,
    };
  }, []);

  const {
    queue: recordingsQueue,
    items: recordingsList,
    busy: recordingsBusy,
    error: recordingsError,
    setError: setRecordingsError,
    refresh: refreshRecordings,
  } = useProcessingQueue<RecordingQueueSnapshot, RecordingListItem>({
    loadSnapshot: loadRecordingsSnapshot,
    getSignature: jobListSignature,
    invalidateEventName: "note-previews-invalidated",
    onSnapshotLoaded: cleanupMissingActiveAudio,
  });

  const playRecording = useCallback(async (audioPath: string) => {
    try {
      const payload = await api.readRecordingAudio(audioPath);
      const bytes = fromBase64(payload.audio_base64);
      const blob = new Blob([bytes], {
        type: payload.mime_type || "audio/mpeg",
      });
      const objectUrl = URL.createObjectURL(blob);
      if (activeAudioObjectUrlRef.current) {
        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
      }
      activeAudioObjectUrlRef.current = objectUrl;
      setActiveAudioPath(audioPath);
      setActiveAudioSrc(objectUrl);
      setRecordingsError(null);
    } catch (error) {
      const message = getErrorMessage(error);
      setRecordingsError(message);
    }
  }, []);

  useEffect(
    () => () => {
      if (activeAudioObjectUrlRef.current) {
        URL.revokeObjectURL(activeAudioObjectUrlRef.current);
        activeAudioObjectUrlRef.current = null;
      }
    },
    []
  );

  const queueRecordingTranscriptions = useCallback(
    async (trigger: "manual" | "auto" = "manual") => {
      if (transcriptionQueueBusyRef.current) {
        return;
      }

      transcriptionQueueBusyRef.current = true;
      setTranscriptionQueueBusy(true);
      try {
        // Local whisper transcription — no API key needed.
        const result = await api.queueLocalTranscriptions(
          syncSettings.whisperModel.trim() || undefined
        );
        const label =
          trigger === "manual"
            ? `Scanned ${result.scanned}, queued ${result.queued}, in-flight ${result.in_flight}.`
            : `Auto queue: scanned ${result.scanned}, queued ${result.queued}.`;
        setRecordingStatusMessage(label);
      } catch (error) {
        const message = getErrorMessage(error);
        setRecordingStatusMessage(message);
      } finally {
        transcriptionQueueBusyRef.current = false;
        setTranscriptionQueueBusy(false);
        void refreshRecordings();
      }
    },
    [refreshRecordings, syncSettings.whisperModel]
  );

  const retriggerTranscription = useCallback(
    async (notePath: string) => {
      try {
        await api.retriggerTranscription(
          notePath,
          syncSettings.whisperModel.trim() || undefined
        );
        setRecordingStatusMessage(`Re-queued ${notePath} for transcription.`);
        void refreshRecordings();
      } catch (error) {
        const message = getErrorMessage(error);
        setRecordingStatusMessage(`Retrigger failed: ${message}`);
      }
    },
    [refreshRecordings, syncSettings.whisperModel]
  );

  const resolveRecordingTargetFolder = useCallback(
    (preferredFolderPath?: string | null) => {
      const preferred = preferredFolderPath?.trim();
      if (preferred) {
        return preferred;
      }
      const active = activeFolder.trim();
      return active || FEED_FOLDER_PATH;
    },
    [activeFolder]
  );

  const handleRecordingReady = useCallback(
    async (blob: Blob, mimeType: string) => {
      const buffer = await blob.arrayBuffer();
      const audioBase64 = toBase64(new Uint8Array(buffer));
      const targetFolder = recordingTargetFolderRef.current || FEED_FOLDER_PATH;
      const result = await api.saveAudioRecording(
        audioBase64,
        mimeType || undefined,
        targetFolder,
        syncSettings.noteFileNameFormat
      );
      await onRecordingComplete(result);
      setRecordingStatusMessage(`Saved ${result.note_path}.`);
      void refreshRecordings();
      await queueRecordingTranscriptions("auto");
    },
    [
      onRecordingComplete,
      queueRecordingTranscriptions,
      refreshRecordings,
      syncSettings.noteFileNameFormat,
    ]
  );

  const {
    isSupported: recordingSupported,
    isRecording: isRecordingAudio,
    isFinalizing: isRecordingFinalizing,
    error: recorderError,
    recordingElapsedLabel,
    startRecording: startRecordingRaw,
    stopRecording: stopRecordingRaw,
  } = useAudioRecorder({
    onRecordingReady: handleRecordingReady,
  });

  const startRecording = useCallback(
    (preferredFolderPath?: string | null) => {
      recordingTargetFolderRef.current =
        resolveRecordingTargetFolder(preferredFolderPath);
      void startRecordingRaw();
    },
    [resolveRecordingTargetFolder, startRecordingRaw]
  );

  const stopRecording = useCallback(() => {
    stopRecordingRaw();
  }, [stopRecordingRaw]);

  const autoQueueTranscriptions = useCallback(
    () => queueRecordingTranscriptions("auto"),
    [queueRecordingTranscriptions]
  );
  useAutoQueueLoop({
    enabled: true,
    delayMs: 0,
    onTick: autoQueueTranscriptions,
  });

  return (
    <RecordingsContext.Provider
      value={{
        recordingSupported,
        isRecordingAudio,
        isRecordingFinalizing,
        recorderError,
        recordingElapsedLabel,
        recordingStatusMessage,
        transcriptionQueueBusy,
        recordingsQueue,
        recordingsList,
        recordingsBusy,
        recordingsError,
        activeAudioPath,
        activeAudioSrc,
        startRecording,
        stopRecording,
        refreshRecordings,
        playRecording,
        queueRecordingTranscriptions,
        retriggerTranscription,
      }}
    >
      {children}
    </RecordingsContext.Provider>
  );
}

export function useRecordings() {
  const context = useContext(RecordingsContext);
  if (!context) {
    throw new Error("useRecordings must be used within a RecordingsProvider");
  }
  return context;
}

import { useCallback, useEffect, useRef, useState } from "react";

type UseAudioRecorderArgs = {
  onRecordingReady: (blob: Blob, mimeType: string) => Promise<void>;
};

const MIME_CANDIDATES = [
  "audio/webm;codecs=opus",
  "audio/webm",
  "audio/mp4",
  "audio/aac",
  "audio/ogg;codecs=opus",
  "audio/mpeg",
];

const pickMimeType = () => {
  if (typeof MediaRecorder === "undefined") {
    return "";
  }
  if (typeof MediaRecorder.isTypeSupported !== "function") {
    return "";
  }
  return MIME_CANDIDATES.find((candidate) => MediaRecorder.isTypeSupported(candidate)) || "";
};

const toErrorMessage = (error: unknown) => {
  if (error instanceof DOMException) {
    if (error.name === "NotAllowedError" || error.name === "PermissionDeniedError") {
      return "Microphone permission is required.";
    }
    if (error.name === "NotFoundError") {
      return "No microphone device was found.";
    }
    return error.message || "Audio recording failed.";
  }
  if (
    typeof error === "object" &&
    error &&
    "message" in error &&
    typeof (error as { message?: unknown }).message === "string"
  ) {
    return (error as { message: string }).message;
  }
  if (error instanceof Error) {
    return error.message;
  }
  return String(error);
};

const formatElapsed = (durationMs: number): string => {
  const totalSeconds = Math.max(0, Math.floor(durationMs / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  if (hours > 0) {
    return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  }
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
};

export const useAudioRecorder = ({ onRecordingReady }: UseAudioRecorderArgs) => {
  const recorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const mimeTypeRef = useRef<string>("");

  const [isRecording, setIsRecording] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [recordingStartedAtMs, setRecordingStartedAtMs] = useState<number | null>(null);
  const [clockNowMs, setClockNowMs] = useState(() => Date.now());

  const isSupported =
    typeof window !== "undefined" &&
    typeof MediaRecorder !== "undefined" &&
    Boolean(navigator.mediaDevices?.getUserMedia);

  const stopStream = useCallback(() => {
    streamRef.current?.getTracks().forEach((track) => track.stop());
    streamRef.current = null;
  }, []);

  useEffect(() => {
    if (!isRecording || !recordingStartedAtMs) {
      return;
    }
    setClockNowMs(Date.now());
    const timer = window.setInterval(() => {
      setClockNowMs(Date.now());
    }, 1000);
    return () => {
      window.clearInterval(timer);
    };
  }, [isRecording, recordingStartedAtMs]);

  const saveBlob = useCallback(
    async (blob: Blob, mimeType: string) => {
      if (blob.size === 0) {
        setError("No audio captured. Try recording again.");
        return;
      }
      setIsFinalizing(true);
      try {
        await onRecordingReady(blob, mimeType || blob.type);
        setError(null);
      } catch (cause) {
        setError(toErrorMessage(cause));
      } finally {
        setIsFinalizing(false);
      }
    },
    [onRecordingReady]
  );

  const startRecording = useCallback(async () => {
    try {
      if (!isSupported) {
        setError("This device does not support audio recording in-app.");
        return;
      }
      if (isRecording || isFinalizing) {
        return;
      }
      setError(null);
      chunksRef.current = [];
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const chosenMimeType = pickMimeType();
      mimeTypeRef.current = chosenMimeType;
      const recorder = chosenMimeType
        ? new MediaRecorder(stream, { mimeType: chosenMimeType })
        : new MediaRecorder(stream);

      recorder.ondataavailable = (event: BlobEvent) => {
        if (event.data.size > 0) {
          chunksRef.current.push(event.data);
        }
      };

      recorder.onerror = () => {
        setError("Audio recorder encountered an error.");
      };

      recorder.onstop = () => {
        recorderRef.current = null;
        setIsRecording(false);
        setRecordingStartedAtMs(null);
        stopStream();

        const blobType = mimeTypeRef.current || "audio/webm";
        const blob = new Blob(chunksRef.current, { type: blobType });
        chunksRef.current = [];
        void saveBlob(blob, mimeTypeRef.current || blob.type);
      };

      recorderRef.current = recorder;
      recorder.start(200);
      setIsRecording(true);
      setClockNowMs(Date.now());
      setRecordingStartedAtMs(Date.now());
    } catch (cause) {
      setError(toErrorMessage(cause));
      stopStream();
    }
  }, [isFinalizing, isRecording, isSupported, saveBlob, stopStream]);

  const stopRecording = useCallback(() => {
    const recorder = recorderRef.current;
    if (!recorder || recorder.state === "inactive") {
      return;
    }
    recorder.stop();
  }, []);

  useEffect(() => {
    return () => {
      const recorder = recorderRef.current;
      if (recorder && recorder.state !== "inactive") {
        recorder.stop();
      }
      stopStream();
    };
  }, [stopStream]);

  const recordingElapsedMs =
    isRecording && recordingStartedAtMs
      ? Math.max(0, clockNowMs - recordingStartedAtMs)
      : null;
  const recordingElapsedLabel =
    recordingElapsedMs !== null ? formatElapsed(recordingElapsedMs) : null;

  const clearError = useCallback(() => setError(null), []);

  return {
    isSupported,
    isRecording,
    isFinalizing,
    error,
    recordingElapsedLabel,
    startRecording,
    stopRecording,
    clearError,
  };
};

import { register } from "@inkibra/tauri-plugin-ota";
import { mountApp } from "./app/main-app";

register(() => {
  mountApp();
});

import { useRef, type ReactNode } from "react";
import { useShallow } from "zustand/react/shallow";

import { AppearanceProvider } from "@/app/state/appearance-store";
import { SelectionProvider, useSelection } from "@/app/state/selection-store";
import { EditorProvider, useEditor } from "@/features/notes/editor/hooks/editor-context";
import { HandwritingProvider } from "@/features/handwriting/hooks/handwriting-context";
import { NotesTreeProvider, useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { ProfilesProvider } from "@/features/profiles/hooks/profiles-context";
import { RecordingsProvider } from "@/features/recording/hooks/recordings-context";
import { SecurityProvider } from "@/features/security/hooks/security-context";
import { GitSyncProvider } from "@/features/sync/hooks/git-sync-context";
import { useLayoutMode } from "@/mobile/use-layout-mode";
import { useBackgroundSave } from "./lifecycle/use-background-save";
import { AppReadinessGate, AppSecurityGate } from "./readiness";

function FlushSaveBridge({
  flushSaveRef,
}: {
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
}) {
  const { flushSave } = useEditor();
  flushSaveRef.current = flushSave;
  return null;
}

function AppLifecycle() {
  const { flushSave } = useEditor();
  useBackgroundSave(flushSave);
  return null;
}

function CaptureFeatureProviders({ children }: { children: ReactNode }) {
  const notesTree = useNotesTree();
  const selection = useSelection(
    useShallow((state) => ({
      activeFolder: state.activeFolder,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setActiveFolder: state.setActiveFolder,
      setSelectedNotes: state.setSelectedNotes,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );
  const editor = useEditor();
  const layoutMode = useLayoutMode();

  const handleCapturedNoteComplete = async (result: {
    folder_path: string;
    note_path: string;
  }) => {
    await notesTree.refreshTree();
    selection.setSelectedFolders(new Set([result.folder_path]));
    selection.setLastSelectedFolder(result.folder_path);
    selection.setActiveFolder(result.folder_path);
    selection.setSelectedNotes(new Set([result.note_path]));
    selection.setLastSelectedNote(result.note_path);
    selection.setActiveNote(result.note_path);
    editor.clearDraft();
  };

  return (
    <RecordingsProvider
      activeFolder={selection.activeFolder}
      layoutMode={layoutMode}
      onRecordingComplete={handleCapturedNoteComplete}
    >
      <HandwritingProvider
        activeFolder={selection.activeFolder}
        layoutMode={layoutMode}
        onHandwritingComplete={handleCapturedNoteComplete}
      >
        {children}
      </HandwritingProvider>
    </RecordingsProvider>
  );
}

function UnlockedAppProviders({
  children,
  flushSaveRef,
}: {
  children: ReactNode;
  flushSaveRef: React.RefObject<(() => Promise<void>) | null>;
}) {
  return (
    <ProfilesProvider flushSaveRef={flushSaveRef}>
      <GitSyncProvider>
        <SelectionProvider>
          <EditorProvider>
            <NotesTreeProvider>
              <FlushSaveBridge flushSaveRef={flushSaveRef} />
              <AppLifecycle />
              <AppReadinessGate>
                <CaptureFeatureProviders>{children}</CaptureFeatureProviders>
              </AppReadinessGate>
            </NotesTreeProvider>
          </EditorProvider>
        </SelectionProvider>
      </GitSyncProvider>
    </ProfilesProvider>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  const flushSaveRef = useRef<(() => Promise<void>) | null>(null);

  return (
    <AppearanceProvider>
      <SecurityProvider>
        <AppSecurityGate>
          <UnlockedAppProviders flushSaveRef={flushSaveRef}>
            {children}
          </UnlockedAppProviders>
        </AppSecurityGate>
      </SecurityProvider>
    </AppearanceProvider>
  );
}

