1	import {
2	  useCallback,
3	  useRef,
4	  useState,
5	  type MouseEvent as ReactMouseEvent,
6	  type RefObject,
7	} from "react";
8	import { LogicalPosition } from "@tauri-apps/api/dpi";
9	import { Menu } from "@tauri-apps/api/menu";
10	import { useShallow } from "zustand/react/shallow";
11	
12	import { useSelection } from "@/app/state/selection-store";
13	import { useEditor } from "@/features/notes/editor/hooks/editor-context";
14	import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
15	import { findNode } from "@/features/notes/navigation/model/tree-ops";
16	import { focusNoScroll } from "@/shared/lib/dom";
17	import { getNoteParentPath } from "@typenotes/shared/notes";
18	import { computeRangeSelection, resolveTargetPaths } from "@/shared/lib/selection";
19	
20	type UseTreeInteractionsArgs = {
21	  /** The folders pane body; focused after a selection change. */
22	  foldersPanelRef: RefObject<HTMLDivElement | null>;
23	  useNativeContextMenus?: boolean;
24	};
25	
26	export type DesktopContextMenuState =
27	  | {
28	      kind: "folder";
29	      x: number;
30	      y: number;
31	      path: string;
32	      targetPaths: string[];
33	    }
34	  | {
35	      kind: "note";
36	      x: number;
37	      y: number;
38	      path: string;
39	      parentPath: string;
40	      targetPaths: string[];
41	    };
42	
43	export type TreeInteractions = {
44	  handleFolderClick: (event: ReactMouseEvent, path: string) => void;
45	  handleToggle: (event: ReactMouseEvent, id: string) => void;
46	  handleNoteClick: (
47	    notePath: string,
48	    event: ReactMouseEvent,
49	    parentPath?: string
50	  ) => void;
51	  handleFolderContextMenu: (
52	    event: ReactMouseEvent,
53	    path: string
54	  ) => Promise<void>;
55	  handleNoteContextMenu: (
56	    event: ReactMouseEvent,
57	    path: string,
58	    parentPath?: string
59	  ) => Promise<void>;
60	  desktopContextMenuState: DesktopContextMenuState | null;
61	  openDesktopContextMenu: (state: DesktopContextMenuState) => void;
62	  closeDesktopContextMenu: () => void;
63	};
64	
65	/**
66	 * Folder/note interaction handlers shared by the desktop and mobile shells:
67	 * range-aware click selection, expand/collapse toggling, and the right-click
68	 * menus used by the tree UI. Desktop can switch to a React/shadcn popup menu;
69	 * mobile keeps the existing action-sheet / native behavior.
70	 */
71	export const useTreeInteractions = ({
72	  foldersPanelRef,
73	  useNativeContextMenus = true,
74	}: UseTreeInteractionsArgs): TreeInteractions => {
75	  const { clearDraft, clearNote } = useEditor();
76	  const {
77	    selectedFolders,
78	    setSelectedFolders,
79	    lastSelectedFolder,
80	    setLastSelectedFolder,
81	    setActiveFolder,
82	    selectedNotes,
83	    setSelectedNotes,
84	    lastSelectedNote,
85	    setLastSelectedNote,
86	    setActiveNote,
87	  } = useSelection(
88	    useShallow((state) => ({
89	      selectedFolders: state.selectedFolders,
90	      setSelectedFolders: state.setSelectedFolders,
91	      lastSelectedFolder: state.lastSelectedFolder,
92	      setLastSelectedFolder: state.setLastSelectedFolder,
93	      setActiveFolder: state.setActiveFolder,
94	      selectedNotes: state.selectedNotes,
95	      setSelectedNotes: state.setSelectedNotes,
96	      lastSelectedNote: state.lastSelectedNote,
97	      setLastSelectedNote: state.setLastSelectedNote,
98	      setActiveNote: state.setActiveNote,
99	    }))
100	  );
101	
102	  const {
103	    tree,
104	    orderedIds,
105	    setExpanded,
106	    deleteFolders,
107	    deleteNotes,
108	    moveNotesToArchive,
109	    startRenameFolder,
110	    showNoteInfo,
111	    shouldNestNotesInNavigation,
112	  } = useNotesTree();
113	
114	  // The native menus are created once and reused; the path each acts on is read
115	  // from a ref set just before popup (menu-item actions can't close over args).
116	  const folderContextPathRef = useRef<string | null>(null);
117	  const noteContextPathRef = useRef<string | null>(null);
118	  const folderMenuPromiseRef = useRef<Promise<Menu> | null>(null);
119	  const noteMenuPromiseRef = useRef<Promise<Menu> | null>(null);
120	
121	  // Latest selection, readable from menu-item actions without re-creating menus.
122	  const selectedFoldersRef = useRef<Set<string>>(new Set());
123	  const selectedNotesRef = useRef<Set<string>>(new Set());
124	  selectedFoldersRef.current = selectedFolders;
125	  selectedNotesRef.current = selectedNotes;
126	
127	  const [desktopContextMenuState, setDesktopContextMenuState] =
128	    useState<DesktopContextMenuState | null>(null);
129	
130	  const openDesktopContextMenu = useCallback(
131	    (state: DesktopContextMenuState) => {
132	      setDesktopContextMenuState(state);
133	    },
134	    []
135	  );
136	
137	  const closeDesktopContextMenu = useCallback(() => {
138	    setDesktopContextMenuState(null);
139	  }, []);
140	
141	  const handleFolderClick = (event: ReactMouseEvent, path: string) => {
142	    event.stopPropagation();
143	    setSelectedFolders(
144	      computeRangeSelection(event, selectedFolders, orderedIds, lastSelectedFolder, path)
145	    );
146	    setLastSelectedFolder(path);
147	    setActiveFolder(path);
148	    setSelectedNotes(new Set());
149	    setLastSelectedNote("");
150	    setActiveNote(null);
151	    clearDraft();
152	    clearNote();
153	    focusNoScroll(foldersPanelRef.current);
154	  };
155	
156	  const handleToggle = (event: ReactMouseEvent, id: string) => {
157	    event.stopPropagation();
158	    setExpanded((prev) => {
159	      const next = new Set(prev);
160	      if (next.has(id)) next.delete(id);
161	      else next.add(id);
162	      return next;
163	    });
164	  };
165	
166	  const getFolderNativeMenu = () => {
167	    if (!folderMenuPromiseRef.current) {
168	      folderMenuPromiseRef.current = Menu.new({
169	        items: [
170	          {
171	            id: "folder.rename",
172	            text: "Rename folder",
173	            action: () => {
174	              const path = folderContextPathRef.current;
175	              if (path) startRenameFolder(path);
176	            },
177	          },
178	          {
179	            id: "folder.delete",
180	            text: "Delete folder",
181	            action: () => {
182	              const path = folderContextPathRef.current;
183	              if (!path) return;
184	              void deleteFolders(resolveTargetPaths(selectedFoldersRef.current, path));
185	            },
186	          },
187	        ],
188	      });
189	    }
190	    return folderMenuPromiseRef.current;
191	  };
192	
193	  const handleFolderContextMenu = async (event: ReactMouseEvent, path: string) => {
194	    event.preventDefault();
195	    event.stopPropagation();
196	    if (!selectedFolders.has(path)) {
197	      setSelectedFolders(new Set([path]));
198	      setLastSelectedFolder(path);
199	    }
200	    setActiveFolder(path);
201	    setSelectedNotes(new Set());
202	    setLastSelectedNote("");
203	    setActiveNote(null);
204	    clearDraft();
205	    clearNote();
206	    focusNoScroll(foldersPanelRef.current);
207	
208	    if (!useNativeContextMenus) {
209	      setDesktopContextMenuState({
210	        kind: "folder",
211	        x: event.clientX,
212	        y: event.clientY,
213	        path,
214	        targetPaths: selectedFolders.has(path)
215	          ? resolveTargetPaths(selectedFoldersRef.current, path)
216	          : [path],
217	      });
218	      return;
219	    }
220	
221	    folderContextPathRef.current = path;
222	    const menu = await getFolderNativeMenu();
223	    await menu.popup(new LogicalPosition(event.clientX, event.clientY));
224	  };
225	
226	  const handleNoteClick = (
227	    notePath: string,
228	    event: ReactMouseEvent,
229	    parentPath?: string
230	  ) => {
231	    const noteParentPath = parentPath ?? getNoteParentPath(notePath);
232	    const parentNode = findNode(tree, noteParentPath);
233	    if (!parentNode) return;
234	    const notePaths = parentNode.notes.map((n) => n.path);
235	    setSelectedNotes(
236	      computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
237	    );
238	    setLastSelectedNote(notePath);
239	    setSelectedFolders(new Set(noteParentPath ? [noteParentPath] : []));
240	    setLastSelectedFolder(noteParentPath);
241	    setActiveFolder(noteParentPath);
242	    setActiveNote(notePath);
243	    if (parentPath !== undefined || shouldNestNotesInNavigation) {
244	      focusNoScroll(foldersPanelRef.current);
245	    }
246	  };
247	
248	  const getNoteNativeMenu = () => {
249	    if (!noteMenuPromiseRef.current) {
250	      noteMenuPromiseRef.current = Menu.new({
251	        items: [
252	          {
253	            id: "note.info",
254	            text: "See info",
255	            action: () => {
256	              const path = noteContextPathRef.current;
257	              if (path) void showNoteInfo(path);
258	            },
259	          },
260	          {
261	            id: "note.delete",
262	            text: "Delete selected",
263	            action: () => {
264	              const path = noteContextPathRef.current;
265	              if (!path) return;
266	              void deleteNotes(resolveTargetPaths(selectedNotesRef.current, path));
267	            },
268	          },
269	          {
270	            id: "note.move.archieve",
271	            text: "Move to Archive",
272	            action: () => {
273	              const path = noteContextPathRef.current;
274	              if (!path) return;
275	              void moveNotesToArchive(resolveTargetPaths(selectedNotesRef.current, path));
276	            },
277	          },
278	        ],
279	      });
280	    }
281	    return noteMenuPromiseRef.current;
282	  };
283	
284	  const handleNoteContextMenu = async (
285	    event: ReactMouseEvent,
286	    path: string,
287	    parentPath?: string
288	  ) => {
