      value={{
        gitStatus,
        gitSyncAction,
        gitSyncError,
        gitSyncBusy,
        gitCommitHistory,
        gitHistoryBusy,
        gitHistoryError,
        refreshGitStatus,
        refreshGitHistory,
        connectGitRepo,
        gitPull,
        gitPush,
        syncNow,
        setGitStatus,
        setGitSyncError,
      }}
    >
      {children}
    </GitSyncContext.Provider>
  );
}

export function useGitSync() {
  const context = useContext(GitSyncContext);
  if (!context) {
    throw new Error("useGitSync must be used within a GitSyncProvider");
  }
