127	  const previewSourceNotes = useMemo<NoteEntry[]>(
128	    () =>
129	      shouldWarmNotePreviews
130	        ? selectPreviewSourceNotes({
131	            layoutMode,
132	            activeFolder,
133	            activeNote,
134	            notes,
135	            feedNotes: feedSourceNotes,
136	            allNotes,
137	            shouldNestNotesInNavigation,
138	          })
139	        : [],
140	    [
141	      shouldWarmNotePreviews,
142	      layoutMode,
143	      activeFolder,
144	      activeNote,
145	      notes,
146	      feedSourceNotes,
147	      allNotes,
148	      shouldNestNotesInNavigation,
149	    ]
150	  );
