1	import { useRef, useState } from "react";
2	import { check, type Update } from "@tauri-apps/plugin-updater";
3	import { relaunch } from "@tauri-apps/plugin-process";
4	import { OTA_APPLY_PENDING_KEY } from "@/shared/constants";
5	import { getErrorMessage } from "@typenotes/shared/errors";
6	
7	type DesktopUpdateState =
8	  | { status: "idle" }
9	  | { status: "checking" }
10	  | { status: "up-to-date" }
11	  | { status: "available"; version: string; notes?: string }
12	  | { status: "downloading"; version: string; downloaded: number; total: number | null }
13	  | { status: "ready"; version: string }
14	  | { status: "error"; message: string };
15	
16	function formatBytes(bytes: number): string {
17	  if (bytes < 1024) return `${bytes} B`;
18	  const units = ["KB", "MB", "GB"];
19	  let value = bytes / 1024;
20	  let unit = 0;
21	  while (value >= 1024 && unit < units.length - 1) {
22	    value /= 1024;
23	    unit += 1;
24	  }
25	  return `${value.toFixed(1)} ${units[unit]}`;
26	}
27	
28	/**
29	 * Native desktop auto-updater. Talks to the Tauri updater plugin, which compares
30	 * the installed app version against the `latest.json` manifest hosted at the
31	 * endpoint configured in tauri.conf.json, then downloads and swaps the whole app
32	 * binary — no .dmg reinstall needed.
33	 */
34	function DesktopAppUpdates() {
35	  const [state, setState] = useState<DesktopUpdateState>({ status: "idle" });
36	  const updateRef = useRef<Update | null>(null);
37	
38	  const checkForUpdates = async () => {
39	    setState({ status: "checking" });
40	    try {
41	      const update = await check();
42	      if (!update) {
43	        setState({ status: "up-to-date" });
44	        return;
45	      }
46	      updateRef.current = update;
47	      setState({ status: "available", version: update.version, notes: update.body });
48	    } catch (error) {
49	      setState({
50	        status: "error",
51	        message: getErrorMessage(error),
52	      });
53	    }
54	  };
55	
56	  const downloadAndInstall = async () => {
57	    const update = updateRef.current;
58	    if (!update) return;
59	
60	    let total: number | null = null;
61	    let downloaded = 0;
62	    setState({ status: "downloading", version: update.version, downloaded: 0, total: null });
63	
64	    try {
65	      await update.downloadAndInstall((event) => {
66	        switch (event.event) {
67	          case "Started":
68	            total = event.data.contentLength ?? null;
69	            setState({ status: "downloading", version: update.version, downloaded: 0, total });
70	            break;
71	          case "Progress":
72	            downloaded += event.data.chunkLength;
73	            setState({ status: "downloading", version: update.version, downloaded, total });
74	            break;
75	          case "Finished":
76	            setState({ status: "ready", version: update.version });
77	            break;
78	        }
79	      });
80	      setState({ status: "ready", version: update.version });
81	      await relaunch();
82	    } catch (error) {
83	      setState({
84	        status: "error",
85	        message: getErrorMessage(error),
86	      });
87	    }
88	  };
89	
90	  const busy = state.status === "checking" || state.status === "downloading";
91	
92	  return (
93	    <section className="space-y-3 rounded-lg border border-border/70 bg-card/30 p-4">
94	      <h3 className="text-sm font-semibold text-foreground">Desktop app</h3>
95	
96	      <div className="grid gap-3 text-sm">
97	        <div className="text-xs text-muted-foreground">Current version: {__APP_VERSION__}</div>
98	
99	        {state.status === "checking" && (
100	          <div className="text-sm text-muted-foreground">Checking for updates…</div>
101	        )}
102	
103	        {state.status === "up-to-date" && (
104	          <div className="text-sm text-green-600 dark:text-green-400">
105	            You're on the latest version.
106	          </div>
107	        )}
108	
109	        {state.status === "available" && (
110	          <div className="space-y-2">
111	            <div className="text-sm text-foreground">
112	              Version <strong>{state.version}</strong> is available.
113	            </div>
114	            {state.notes && <div className="text-xs text-muted-foreground">{state.notes}</div>}
115	            <button
116	              type="button"
117	              className="rounded-md bg-primary px-3 py-1.5 text-sm font-medium text-primary-foreground hover:bg-primary/90"
118	              onClick={downloadAndInstall}
119	            >
120	              Download & install
121	            </button>
122	          </div>
123	        )}
124	
125	        {state.status === "downloading" && (
126	          <div className="text-sm text-muted-foreground">
127	            Downloading {state.version}…{" "}
128	            {state.total
129	              ? `${formatBytes(state.downloaded)} / ${formatBytes(state.total)}`
130	              : formatBytes(state.downloaded)}
131	          </div>
132	        )}
133	
134	        {state.status === "ready" && (
135	          <div className="text-sm text-muted-foreground">
136	            Update installed. Restarting…
137	          </div>
138	        )}
139	
140	        {state.status === "error" && (
141	          <div className="text-sm text-red-600 dark:text-red-400">{state.message}</div>
142	        )}
143	
144	        {!busy && state.status !== "available" && state.status !== "ready" && (
145	          <button
146	            type="button"
147	            className="w-fit rounded-md border border-border px-3 py-1.5 text-sm font-medium text-foreground hover:bg-accent"
148	            onClick={checkForUpdates}
149	          >
150	            Check for updates
151	          </button>
152	        )}
153	      </div>
154	    </section>
155	  );
156	}
157	
158	type OtaState =
159	  | { status: "idle" }
160	  | { status: "checking" }
161	  | { status: "up-to-date" }
162	  | { status: "available"; version: string; notes?: string }
163	  | { status: "error"; message: string };
164	
165	/**
166	 * OTA JS-bundle updates (used on iOS via the inkibra OTA plugin). Fetches a
167	 * manifest and reloads into the bundled web app — distinct from the native
168	 * desktop updater above, which swaps the whole binary.
169	 */
170	function OtaUpdates() {
171	  const [state, setState] = useState<OtaState>({ status: "idle" });
172	
173	  const checkForUpdates = async () => {
174	    const manifestUrl = import.meta.env.VITE_OTA_MANIFEST_URL?.trim();
175	    if (!manifestUrl) {
176	      setState({ status: "error", message: "No update URL configured." });
177	      return;
178	    }
179	
180	    setState({ status: "checking" });
181	
182	    try {
183	      const response = await fetch(manifestUrl, { cache: "no-store" });
184	      if (!response.ok) {
185	        setState({ status: "error", message: `Failed to fetch manifest (${response.status}).` });
186	        return;
187	      }
188	
189	      const manifest: { version?: string; notes?: string } = await response.json();
190	      if (!manifest.version) {
191	        setState({ status: "error", message: "Invalid manifest format." });
192	        return;
193	      }
194	
195	      if (manifest.version === __APP_VERSION__) {
196	        setState({ status: "up-to-date" });
197	      } else {
198	        setState({ status: "available", version: manifest.version, notes: manifest.notes });
199	      }
200	    } catch (error) {
201	      setState({
202	        status: "error",
203	        message: error instanceof Error ? error.message : "Unknown error.",
204	      });
205	    }
206	  };
207	
208	  const applyUpdate = () => {
209	    window.localStorage.setItem(OTA_APPLY_PENDING_KEY, "true");
210	    window.location.reload();
211	  };
212	
213	  return (
214	    <section className="space-y-3 rounded-lg border border-border/70 bg-card/30 p-4">
215	      <h3 className="text-sm font-semibold text-foreground">OTA updates (iOS)</h3>
216	
217	      <div className="grid gap-3 text-sm">
218	        <div className="text-xs text-muted-foreground">Current version: {__APP_VERSION__}</div>
219	
220	        {state.status === "checking" && (
221	          <div className="text-sm text-muted-foreground">Checking for updates...</div>
222	        )}
223	
224	        {state.status === "up-to-date" && (
225	          <div className="text-sm text-green-600 dark:text-green-400">
226	            You're on the latest version.
227	          </div>
228	        )}
229	
230	        {state.status === "available" && (
231	          <div className="space-y-2">
232	            <div className="text-sm text-foreground">
