2	import { useCallback, type RefObject } from "react";
3	
4	import * as api from "@/features/notes/api/notes-api";
5	import {
6	  ARCHIEVE_FOLDER_PATH,
7	  FEED_FOLDER_PATH,
8	  isSystemFolder,
9	} from "@typenotes/shared/constants";
10	import { confirmAction, focusNoScroll } from "@/shared/lib/dom";
11	import { getNoteParentPath } from "@typenotes/shared/notes";
12	import type { ProfileSyncSettings } from "@typenotes/shared/types";
13	import { applyFolderRenameToSelection, collectNotesForFlattening } from "../model/notes-tree-model";
14	import { findNode } from "@/features/notes/navigation/model/tree-ops";
15	import type { FolderNode } from "@typenotes/shared/types";
16	
17	type UseNotesTreeActionsArgs = {
18	  tree: FolderNode | null;
19	  syncSettings: ProfileSyncSettings;
20	  refreshTree: () => Promise<void>;
21	  rightPaneRef: RefObject<HTMLDivElement | null>;
22	  selectedFolders: Set<string>;
23	  setSelectedFolders: React.Dispatch<React.SetStateAction<Set<string>>>;
24	  setLastSelectedFolder: (path: string) => void;
25	  activeFolder: string;
26	  setActiveFolder: (path: string) => void;
27	  setSelectedNotes: React.Dispatch<React.SetStateAction<Set<string>>>;
28	  setLastSelectedNote: (path: string) => void;
29	  activeNote: string | null;
30	  setActiveNote: (path: string | null) => void;
31	  clearDraft: () => void;
32	  clearNote: () => void;
33	  renamingFolder: string | null;
34	  setRenamingFolder: (path: string | null) => void;
35	  renameValue: string;
36	  setRenameValue: (value: string) => void;
37	};
38	
39	export function useNotesTreeActions({
40	  tree,
41	  syncSettings,
42	  refreshTree,
43	  rightPaneRef,
44	  selectedFolders,
45	  setSelectedFolders,
46	  setLastSelectedFolder,
47	  activeFolder,
48	  setActiveFolder,
49	  setSelectedNotes,
50	  setLastSelectedNote,
51	  activeNote,
52	  setActiveNote,
53	  clearDraft,
54	  clearNote,
55	  renamingFolder,
56	  setRenamingFolder,
57	  renameValue,
58	  setRenameValue,
59	}: UseNotesTreeActionsArgs) {
60	  const createNewNote = useCallback(
61	    async (
62	      preferredFolderPath?: string,
63	      initialContent = "",
64	      targetTimestampMs?: number
65	    ) => {
66	      const treeSnapshot = tree ?? (await api.getTree());
67	      const initialFolderPath = preferredFolderPath?.trim() || FEED_FOLDER_PATH;
68	      const targetNode =
69	        findNode(treeSnapshot, initialFolderPath) || findNode(treeSnapshot, FEED_FOLDER_PATH);
70	      if (!targetNode) return null;
71	      const folderPath = targetNode.path;
72	      const created = await api.createNote(
73	        folderPath,
74	        initialContent,
75	        targetTimestampMs,
76	        syncSettings.noteFileNameFormat
77	      );
78	      const path = created.path;
79	      await refreshTree();
80	
81	      // New note creation is a workflow, not just a write: refresh the tree,
82	      // sync selection, and hand focus to the editor in one pass.
83	      setSelectedFolders(new Set([folderPath]));
84	      setLastSelectedFolder(folderPath);
85	      setActiveFolder(folderPath);
86	      setSelectedNotes(new Set([path]));
87	      setLastSelectedNote(path);
88	      setActiveNote(path);
89	      clearDraft();
90	
91	      requestAnimationFrame(() => {
92	        const editorElement =
93	          rightPaneRef.current?.querySelector<HTMLElement>(
94	            ".tiptap-content[contenteditable='true']"
95	          ) || rightPaneRef.current;
96	        focusNoScroll(editorElement);
97	      });
98	
99	      return path;
100	    },
101	    [
102	      clearDraft,
103	      refreshTree,
104	      rightPaneRef,
105	      setActiveFolder,
106	      setActiveNote,
107	      setLastSelectedFolder,
108	      setLastSelectedNote,
109	      setSelectedFolders,
110	      setSelectedNotes,
111	      syncSettings.noteFileNameFormat,
112	      tree,
113	    ]
114	  );
115	
116	  const applyFolderRename = useCallback(
117	    (oldPath: string, newPath: string) => {
118	      const next = applyFolderRenameToSelection(
119	        activeFolder,
120	        selectedFolders,
121	        oldPath,
122	        newPath
123	      );
124	      setActiveFolder(next.activeFolder);
125	      if (next.selectedFolderChanged) {
126	        setSelectedFolders(next.selectedFolders);
127	        setLastSelectedFolder(newPath);
128	      }
129	    },
130	    [activeFolder, selectedFolders, setActiveFolder, setLastSelectedFolder, setSelectedFolders]
131	  );
132	
133	  const startRenameFolder = useCallback(
134	    (path: string) => {
135	      if (isSystemFolder(path)) {
136	        window.alert(`"${path}" is a fixed folder and cannot be renamed.`);
137	        return;
138	      }
139	      const name = path.split("/").pop() || "";
140	      setRenamingFolder(path);
141	      setRenameValue(name);
142	    },
143	    [setRenamingFolder, setRenameValue]
144	  );
145	
146	  const submitRenameFolder = useCallback(async () => {
147	    if (!renamingFolder || !renameValue.trim()) {
148	      setRenamingFolder(null);
149	      return;
150	    }
151	    const oldPath = renamingFolder;
152	    const newPath = await api.renameItem(oldPath, renameValue.trim());
153	    setRenamingFolder(null);
154	    setRenameValue("");
155	    await refreshTree();
156	    applyFolderRename(oldPath, newPath);
157	  }, [applyFolderRename, refreshTree, renamingFolder, renameValue, setRenamingFolder, setRenameValue]);
158	
159	  const cancelRenameFolder = useCallback(() => {
160	    setRenamingFolder(null);
161	    setRenameValue("");
162	  }, [setRenamingFolder, setRenameValue]);
163	
164	  const deleteFolders = useCallback(
165	    async (paths: string[]) => {
166	      if (paths.length === 0) return;
167	      if (paths.some(isSystemFolder)) {
168	        window.alert(`"Feed" and "Archieve" are fixed folders and cannot be deleted.`);
169	        return;
170	      }
171	      const confirmed = await confirmAction(`Delete ${paths.length} folder(s)?`);
172	      if (!confirmed) return;
173	      await api.deleteItems(paths);
174	      setSelectedFolders(new Set());
175	      if (paths.includes(activeFolder)) setActiveFolder("");
176	      await refreshTree();
177	    },
178	    [activeFolder, refreshTree, setActiveFolder, setSelectedFolders]
179	  );
180	
181	  const deleteNotes = useCallback(
182	    async (paths: string[]) => {
183	      if (paths.length === 0) return false;
184	      const confirmed = await confirmAction(`Delete ${paths.length} note(s)?`);
185	      if (!confirmed) return false;
186	      await api.deleteItems(paths);
187	      setSelectedNotes(new Set());
188	      setLastSelectedNote("");
189	      if (paths.includes(activeNote || "")) {
190	        setActiveNote(null);
191	        clearNote();
192	      }
193	      await refreshTree();
194	      return true;
195	    },
196	    [activeNote, clearNote, refreshTree, setActiveNote, setLastSelectedNote, setSelectedNotes]
197	  );
198	
199	  const moveNotesToArchive = useCallback(
200	    async (paths: string[]) => {
201	      if (paths.length === 0) return;
202	      await api.moveItems(paths, ARCHIEVE_FOLDER_PATH);
203	      setSelectedNotes(new Set());
204	      setLastSelectedNote("");
205	      setActiveNote(null);
206	      clearNote();
207	      setSelectedFolders(new Set([ARCHIEVE_FOLDER_PATH]));
208	      setLastSelectedFolder(ARCHIEVE_FOLDER_PATH);
209	      setActiveFolder(ARCHIEVE_FOLDER_PATH);
210	      await refreshTree();
211	    },
212	    [
213	      clearNote,
214	      refreshTree,
215	      setActiveFolder,
216	      setActiveNote,
217	      setLastSelectedFolder,
218	      setLastSelectedNote,
219	      setSelectedFolders,
220	      setSelectedNotes,
221	    ]
222	  );
223	
224	  const moveNotesToFolder = useCallback(
225	    async (paths: string[], destinationPath: string) => {
226	      const normalizedDestination = destinationPath.trim();
227	      if (paths.length === 0 || !normalizedDestination) {
228	        return;
229	      }
230	      await api.moveItems(paths, normalizedDestination);
231	      setSelectedNotes(new Set());
232	      setLastSelectedNote("");
233	      setActiveNote(null);
234	      clearNote();

